function validate([transactions]) {
  if (!Array.isArray(transactions) || transactions.length > 1000) return 'transactions holds at most 1000 strings.';
  for (const text of transactions) {
    const match = typeof text === 'string' && /^[a-z]{1,10},(\d{1,4}),(\d{1,4}),[a-z]{1,10}$/.exec(text);
    if (!match) return 'Each transaction looks like "name,time,amount,city" with lowercase name and city of 1 to 10 letters.';
    if (Number(match[1]) > 1000) return 'time is between 0 and 1000.';
    if (Number(match[2]) > 2000) return 'amount is between 0 and 2000.';
  }
  return null;
}

