function invalidTransactions(transactions) {
  const records = transactions.map(text => {
    const [name, time, amount, city] = text.split(',');
    return { name, time: Number(time), amount: Number(amount), city };
  });
  const citiesAt = new Map();
  for (const { name, time, city } of records) {
    const key = name + ',' + time;
    if (!citiesAt.has(key)) {
      citiesAt.set(key, new Set());
    }
    citiesAt.get(key).add(city);
  }
  const invalid = [];
  for (let i = 0; i < records.length; i++) {
    const { name, time, amount, city } = records[i];
    let bad = amount > 1000;
    for (let t = time - 60; t <= time + 60 && !bad; t++) {
      const cities = citiesAt.get(name + ',' + t);
      if (cities && (cities.size > 1 || !cities.has(city))) {
        bad = true;
      }
    }
    if (bad) {
      invalid.push(transactions[i]);
    }
  }
  return invalid;
}

