function invalidTransactions(transactions) {
  // Compare every pair of transactions directly.
  const parts = transactions.map(text => text.split(','));
  const result = [];
  for (let i = 0; i < parts.length; i++) {
    let flagged = parseInt(parts[i][2], 10) > 1000;
    for (let j = 0; j < parts.length && !flagged; j++) {
      if (i === j) continue;
      const sameName = parts[i][0] === parts[j][0];
      const otherCity = parts[i][3] !== parts[j][3];
      const gap = Math.abs(parseInt(parts[i][1], 10) - parseInt(parts[j][1], 10));
      if (sameName && otherCity && gap <= 60) flagged = true;
    }
    if (flagged) result.push(transactions[i]);
  }
  return result;
}

