function generate(rand, size) {
  const pick = (list) => list[Math.floor(rand() * list.length)];
  const nameBank = ["alice", "bob", "chen", "dana", "eli", "fatima", "gus", "hana", "ivan", "jo", "kai", "lena", "mo", "nia", "omar", "pia", "quinn", "raj", "sara", "tom", "uma", "vic", "wen", "xi", "yara", "zed"];
  const cityBank = ["mtv", "beijing", "paris", "rome", "lagos", "lima"];
  const n = size === 'large' ? 1000 : 1 + Math.floor(rand() * 8);
  // Large inputs combine bank names with a suffix so that each name has only a few transactions.
  const names = size === 'large'
    ? Array.from({ length: 100 + Math.floor(rand() * 400) }, () => pick(nameBank) + 'abcdefghij'[Math.floor(rand() * 10)])
    : nameBank.slice(0, 1 + Math.floor(rand() * 3));
  const cities = cityBank.slice(0, 1 + Math.floor(rand() * (size === 'large' ? 6 : 3)));
  const start = Math.floor(rand() * 850);
  const span = size === 'large' ? 1001 : 1 + Math.floor(rand() * 150);
  const transactions = Array.from({ length: n }, () => {
    const time = size === 'large' ? Math.floor(rand() * 1001) : Math.min(1000, start + Math.floor(rand() * span));
    const roll = rand();
    const amount = roll < 0.1 ? 1000 : roll < 0.2 ? 1001 : Math.floor(rand() * 2001);
    return pick(names) + ',' + time + ',' + amount + ',' + pick(cities);
  });
  if (size !== 'large' && rand() < 0.2) transactions.push(transactions[Math.floor(rand() * transactions.length)]);
  return [transactions];
}
